// word-frequency (cpp entry) -- count 3,000,000 picks from a 64-word
// vocabulary generated by a pinned integer LCG, then fold the counts into one
// deterministic checksum.
//
// Build:  g++ -std=c++20 -O3 -o word-frequency.exe main.cpp
// Run:    word-frequency.exe
//
// Same workload and same output in every language entry. This is the
// hash-map-shaped task: every pick is a string-keyed lookup + increment, and
// the final fold walks the vocabulary in a fixed order so no language's map
// iteration order can leak into the output.

#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

static const long long kCorpus = 3000000;
static const long long kVocab = 64;

static std::string wordFor(int index) {
    std::string word = "word";
    if (index < 10) word += "0";
    word += std::to_string(index);
    return word;
}

int main() {
    std::vector<std::string> words((size_t)kVocab);
    for (int i = 0; i < (int)kVocab; ++i) words[(size_t)i] = wordFor(i);

    std::unordered_map<std::string, long long> counts;
    counts.reserve(256);

    long long state = 1;
    for (long long k = 0; k < kCorpus; ++k) {
        state = (state * 48271) % 2147483647;
        counts[words[(size_t)(state % kVocab)]]++;
    }

    long long checksum = 0;
    for (int i = 0; i < (int)kVocab; ++i) {
        checksum = (checksum * 31 + counts[words[(size_t)i]]) % 1000000007;
    }
    std::cout << checksum << "\n";
    return 0;
}
